        Chapter(
            "leadership",
            "👩‍💼 Leadership, Teams & Motivation",
            "Leadership Styles · Tuckman · Motivation Theories · Power Types · Situational Leadership",
            "People domain",
            listOf(
                s("Leadership Styles", tableHeaders = listOf("Style", "Description", "When to Use", "PMI View"), tableRows = listOf(listOf("Servant Leadership", "PM SERVES the team; removes impediments; puts team needs first; enables success", "Agile contexts; high-performing teams; empowered cultures", "✅ PMI's preferred style — especially for agile"), listOf("Transformational", "Inspires through vision, purpose, and passion for change; challenges status quo", "Change initiatives; motivating teams through difficulty", "✅ Effective for driving innovation"), listOf("Situational", "Adapts leadership style to team maturity level and task complexity", "Most practical — applies across all project types", "✅ Flexible and context-appropriate"), listOf("Transactional", "Rewards for performance; penalties for non-performance; exchange-based", "Routine, well-defined, structured work", "Moderate — can limit creativity"), listOf("Laissez-faire", "Hands-off; minimal direction; team fully autonomous", "Expert teams; research; high-trust contexts", "Use with caution — can mean abdication"), listOf("Democratic/Participative", "Involves team in decisions; builds consensus; collaborative", "Complex decisions requiring broad input and buy-in", "Good for major decisions and change"), listOf("Autocratic/Directive", "PM decides alone; immediate compliance expected", "True emergencies; inexperienced teams needing direction; safety situations", "Only appropriate in genuine crises"))),
                s("Leadership Styles", "PMBOK 8: Leadership is SHARED — any team member, stakeholder, or professional can demonstrate leadership behaviours at any point. Leadership ≠ authority. Authority = position. Leadership = inspiring others.", SectionKind.KEY),
                s("Team Development — Tuckman's Model", "Forming→Storming→Norming→Performing→Adjourning"),
                s("Team Development — Tuckman's Model", tableHeaders = listOf("Stage", "Team Behaviour", "PM Action"), tableRows = listOf(listOf("Forming", "Polite; cautious; dependent on leader; unclear roles and expectations", "Define roles clearly; set expectations; build relationships; orient the team"), listOf("Storming", "Conflict; power struggles; frustration; differing opinions on approach", "Facilitate conflict resolution; maintain focus on goals; coach through tension"), listOf("Norming", "Team establishes norms; cooperation improves; trust builds; roles clarified", "Reinforce positive behaviours; empower team; begin stepping back as leader"), listOf("Performing", "High performance; self-organising; minimal supervision needed; interdependent", "Delegate; support; celebrate successes; remove obstacles as they arise"), listOf("Adjourning", "Project ends; team disbands; mixed emotions (pride, sadness, uncertainty)", "Recognise contributions; celebrate achievements; capture lessons learned"))),
                s("Team Development — Tuckman's Model", "Teams can move BACKWARDS through stages when team composition changes, major conflict occurs, or a challenging new phase begins. This is normal and expected. Storming may recur.", SectionKind.TIP),
                s("Motivation Theories — Detailed", tableHeaders = listOf("Theory", "Key Concept", "What It Means for a PM"), tableRows = listOf(listOf("Maslow's Hierarchy of Needs", "Five levels: Physiological → Safety → Social → Esteem → Self-Actualisation. Lower needs must be met before higher ones motivate.", "If basic needs (pay, safety, job security) aren't met, recognition and growth won't motivate. Address the level they are actually at."), listOf("Herzberg's Two-Factor Theory", "Hygiene Factors (pay, conditions, security) PREVENT dissatisfaction but do NOT create motivation. Motivators (achievement, recognition, meaningful work, responsibility, growth) create TRUE satisfaction and motivation.", "Pay alone won't motivate your team — they also need recognition, challenging work, and growth opportunities. Hygiene factors are a floor, not a ceiling."), listOf("McGregor Theory X", "People inherently dislike work; must be controlled, directed, and threatened to perform.", "Leads to authoritarian, micromanaging style. PMI does NOT endorse this."), listOf("McGregor Theory Y", "People are self-motivated; find work natural; seek responsibility; are creative when given the chance.", "PMI's preferred view — servant leadership and empowered culture align with Theory Y."), listOf("McClelland's Achievement Theory", "Three primary needs: Achievement (mastery, accomplishing goals), Affiliation (belonging, relationships), Power (influence, leading others).", "Match team member roles to their dominant need. Achievement-oriented → challenging goals. Affiliation → collaborative roles. Power → leadership opportunities."), listOf("Expectancy Theory (Vroom)", "Motivation = Expectancy (effort leads to performance) × Instrumentality (performance leads to reward) × Valence (reward is valued).", "All three must be present. If team doesn't believe effort leads to success, or success won't be rewarded, or the reward isn't valued — motivation drops."))),
                s("Motivation Theories — Detailed", "Herzberg is THE most tested motivation theory. Hygiene factors prevent DIS-satisfaction (two different scales — not two ends of one scale). Salary preventing unhappiness ≠ salary creating happiness.", SectionKind.DANGER),
                s("Power Types", tableHeaders = listOf("Power Type", "Source", "PMI Preference", "Why?"), tableRows = listOf(listOf("Expert", "Knowledge, skill, and experience in a relevant domain", "✅ Highest — most sustainable", "Respected regardless of title; does not depend on position; builds credibility"), listOf("Referent", "Personal charisma, trust built over time, quality relationships", "✅ High — builds loyalty", "Creates genuine followership; earned through consistent trustworthy behaviour"), listOf("Reward", "Ability to give incentives, recognition, resources, promotions", "Moderate — use carefully", "Effective but can create dependency on external rewards; may breed entitlement"), listOf("Legitimate / Formal", "Title or position in the organisational hierarchy", "Moderate — limited effectiveness", "Authority without influence is fragile; people comply but may not commit"), listOf("Penalty / Coercive", "Ability to punish, withhold, or threaten consequences", "❌ Lowest — avoid", "Damages trust, creates resentment, kills psychological safety and creativity"))),
                s("Virtual / Distributed Teams", "• Accommodate different time zones and cultural differences in all communications\n• Use video conferencing for important discussions — see faces, build relationships\n• Establish clear communication norms and response time expectations\n• Co-location is always preferred when feasible — face-to-face builds trust fastest\n• Cultural intelligence: respect language barriers, different communication styles, varied norms\n• Scrum: Daily Scrum should be scheduled for a time that works for all time zones"),
                s("Situational Leadership — Hersey & Blanchard", "The leader adapts their style based on the follower's competence and commitment:"),
                s("Situational Leadership — Hersey & Blanchard", tableHeaders = listOf("Style", "Directive", "Supportive", "When Team Is...", "Leader Does..."), tableRows = listOf(listOf("S1 — Directing/Telling", "High", "Low", "Low competence, high commitment (enthusiastic beginner)", "Gives specific instructions; supervises closely"), listOf("S2 — Coaching/Selling", "High", "High", "Some competence, low commitment (disillusioned learner)", "Explains decisions; solicits input; encourages"), listOf("S3 — Supporting/Participating", "Low", "High", "High competence, variable commitment (capable but cautious)", "Shares decision-making; facilitates"), listOf("S4 — Delegating", "Low", "Low", "High competence, high commitment (self-reliant achiever)", "Hands over responsibility; monitors lightly"))),
                s("Situational Leadership — Hersey & Blanchard", "Exam point: Match the style to the person and task — not one style for the whole team. A senior engineer may need S4 on familiar work but S2 on a new technology.", SectionKind.TIP),
                s("Team Charter", "The Team Charter (also called Team Agreement or Working Agreement) documents team values, agreements, and operating guidelines. Created BY the team, not FOR the team."),
                s("Team Charter", tableHeaders = listOf("Section", "Content"), tableRows = listOf(listOf("Team Values", "What the team believes in — respect, transparency, quality"), listOf("Communication Guidelines", "Preferred channels, response time expectations, meeting norms"), listOf("Decision-Making Criteria", "How decisions are made — consensus, majority, PO decides"), listOf("Conflict Resolution Process", "How the team handles disagreements"), listOf("Meeting Guidelines", "Attendance, punctuality, agenda, facilitation"), listOf("Ground Rules", "Working hours, core hours for virtual teams, tool usage"))),
                s("Team Charter", "When a question involves team norms, working agreements, or \"how the team operates\" — the answer often involves referencing or updating the Team Charter.", SectionKind.KEY),
                s("Recognition and Rewards", "• Rewards should be based on agreed criteria in the resource management plan\n• Only reward desirable behaviour — rewarding overtime encourages overtime culture\n• Consider cultural differences — public recognition is valued in some cultures, embarrassing in others\n• Intrinsic rewards (autonomy, mastery, purpose) are often more powerful than extrinsic (money)\n• Recognise the TEAM as well as individuals — avoid creating internal competition\n• Timeliness matters — recognise promptly, not months later"),
                s("Team Building Activities", tableHeaders = listOf("Stage", "Activity Type"), tableRows = listOf(listOf("Kick-off", "Introductions, charter development, vision sharing"), listOf("Ongoing", "Regular check-ins, celebrating milestones, social events"), listOf("Virtual teams", "Video introductions, virtual coffee breaks, shared online spaces"), listOf("Conflict phase", "Facilitated workshops, structured problem-solving sessions"), listOf("Closure", "Retrospective, celebration, recognition of contributions"))),
                s("Coaching vs. Mentoring vs. Training", tableHeaders = listOf("Method", "Focus", "Duration", "Who Leads"), tableRows = listOf(listOf("Training", "Specific skill acquisition", "Short; structured", "Trainer/instructor"), listOf("Coaching", "Performance improvement through questions and guidance", "Medium; goal-focused", "Coach (asks, does not tell)"), listOf("Mentoring", "Career development; sharing experience and wisdom", "Long-term; relationship-based", "Mentor (shares experience)"))),
                s("Decision-Making Techniques", tableHeaders = listOf("Technique", "Description", "When to Use"), tableRows = listOf(listOf("Unanimity", "Everyone agrees", "Small groups; critical decisions"), listOf("Majority", "More than 50% agree", "Larger groups; time constraints"), listOf("Plurality", "Largest block decides (even if <50%)", "Multiple options; no clear majority"), listOf("Autocratic", "One person decides", "Emergencies; clear authority"), listOf("Consensus", "Everyone can live with the decision (not necessarily first choice)", "Agile teams; buy-in critical"), listOf("Fist of Five", "Vote with fingers (5 = fully support, 1 = strongly oppose)", "Quick agile consensus check"), listOf("Dot Voting", "Each person places dots on preferred options", "Prioritising many options quickly"))),
                s("Worked example — Tuckman Stages — What They Actually Look Like", "Project: New payments compliance project. Team of 8 assembled from across the organisation.\n\nWEEK 1–2 — FORMING:\n\nTeam is polite but cautious. Nobody disagrees openly. Attendance at meetings is perfect. People look to the PM for every decision. Nobody volunteers opinions on the technical approach.\n\n→ PM action: Define roles clearly in the team charter. Create a \"getting to know you\" session. Set clear expectations for the project. Establish communication norms.\n\nWEEK 3–5 — STORMING:\n\nA heated debate breaks out between the backend developer and the QA lead about test coverage requirements. The developer says \"we don't have time for 90% coverage.\" The QA lead says \"anything less is a regulatory risk.\" Two team members stop talking directly and communicate only through the PM. Sprint velocity drops 30%.\n\n→ PM action: Meet individually with both parties. Understand each perspective. Bring them together with a shared goal (\"what does 'good enough' coverage mean for this specific regulation?\"). Reference the quality plan. Facilitate a decision.\n\nWEEK 6–8 — NORMING:\n\nThe team agrees on a tiered testing approach: 90% for payment logic, 70% for reporting. Norms establish: decisions made by the team, not routed through PM. Velocity recovers. Team members start helping each other without being asked.\n\n→ PM action: Reinforce the positive norms. Step back slightly from day-to-day decisions. Empower team leads.\n\nWEEK 9–20 — PERFORMING:\n\nTeam self-organises daily standups without PM facilitation. Retrospectives generate concrete improvements. Velocity is 15% above initial baseline. Team catches a regulatory interpretation error before it becomes a defect.\n\n→ PM action: Delegate fully. Remove obstacles. Celebrate wins. Focus on stakeholder management and external impediments.\n\nWEEK 21 — ADJOURNING:\n\nProject completes. Several team members are quiet. The developer who fought with the QA lead says \"I'll miss this team.\" PM organises a celebration, writes personal notes of thanks to each member, and ensures lessons are captured before the team disperses.", SectionKind.TIP),
                s("Worked example — Motivation Theories — Applied to Real Situations", "SITUATION 1 — Maslow applied:\n\nA developer in your remote team in Pune mentions that the company has not processed his expenses from last month and he is struggling financially.\n\n→ Safety needs not met. Recognition awards and \"stretch\" projects will have ZERO motivational effect until this is resolved. PM action: escalate the expense issue to HR/Finance immediately. This is a hygiene/safety issue.\n\nSITUATION 2 — Herzberg applied:\n\nYou give the team a 15% salary increase. Two weeks later, velocity is the same. A team member says \"I still feel like my work doesn't matter.\"\n\n→ The salary addressed a hygiene factor (prevented dissatisfaction) but did not create motivation. The team member needs a MOTIVATOR — meaningful work, recognition, growth opportunity. PM action: assign them to a high-impact module and acknowledge their expertise publicly.\n\nSITUATION 3 — McClelland applied:\n\nYou have two senior developers with equal skills. Dev A loves technical challenges, works alone best, gets frustrated in meetings. Dev B is a natural mentor, energised by collaboration, volunteers to lead the interns.\n\n→ Dev A has high Achievement need → assign complex solo research spikes\n\n→ Dev B has high Affiliation need → make them the team's knowledge-sharing lead, pair with juniors\n\nSITUATION 4 — Pink's model applied:\n\nA talented product analyst keeps arriving late and missing deadlines despite having market-rate pay, a good manager, and interesting work.\n\n→ Check for AUTONOMY: Does she control HOW she works, or is every task micro-managed?\n\n→ Check for MASTERY: Is she learning, or doing the same thing repeatedly?\n\n→ Check for PURPOSE: Does she see how her work connects to the product's impact?\n\nPM action: have a 1:1 to explore what's missing. The answer is usually in one of these three areas.", SectionKind.TIP),
                s("Worked example — Ethics — Applying the EDMF Framework in Real Scenarios", "Scenario: You are PM on a healthcare data migration project. A vendor account manager takes you to an expensive dinner (₹15,000/person) during the evaluation phase. At dinner, he hints that his company can \"adjust the proposal\" if needed.\n\nApply EDMF:\n\nStep 1 — Assessment:\n\nFacts: You are in vendor evaluation. This is an expensive gift/entertainment. There is a hint of proposal flexibility. This may constitute bribery. Affected: your organisation (fairness of selection), other vendors (unfair advantage), patients (if wrong vendor selected).\n\nStep 2 — Alternatives:\n\nA) Accept dinner and continue normally\n\nB) Accept dinner, declare it, and recuse yourself from evaluation\n\nC) Decline the dinner\n\nD) Decline, document the interaction, and report to your manager\n\nStep 3 — Analysis:\n\nA violates Fairness (conflict of interest) and Honesty (the hint was a corruption attempt).\n\nB: too late — attending created the appearance of impropriety.\n\nC: better, but the \"adjusted proposal\" hint should be reported.\n\nD: upholds all four PMI values.\n\nStep 4 — Application:\n\nPMI Code: Fairness (proactively disclose real or potential conflicts, do not engage in activities creating conflicts). Honesty (do not engage in behaviour designed to personally gain). Responsibility (report unethical conduct).\n\nStep 5 — Action:\n\nDecline the dinner politely (\"I appreciate the invitation but must decline during the evaluation period\"). Document the dinner invitation and the \"adjusted proposal\" comment in writing. Report to your manager and procurement officer. The vendor may need to be disqualified if the conduct constitutes an improper offer.\n\nExam application: Any time you see \"gift during procurement\" or \"vendor offers something extra\" — the answer involves declining, disclosing, and likely reporting.", SectionKind.TIP),
                s("Leadership Styles — Complete Reference with Exam Application", tableHeaders = listOf("Style", "Core Approach", "When Most Effective", "Exam Trigger", "Wrong When"), tableRows = listOf(listOf("Visionary/Authoritative", "Sets a compelling direction; explains WHY; gives autonomy on HOW", "Team needs direction and inspiration but wants freedom on execution", "Team is capable but lacks a clear goal or purpose", "Team needs specific technical guidance; crisis requiring precise direction"), listOf("Coaching", "Develops people; invests time in growth; long view on team capability", "Individual has potential but needs guided development", "Team member needs skill development; long-term relationship", "Crisis; time pressure; team member already expert"), listOf("Affiliative", "Puts relationships and harmony first; builds emotional bonds", "Team recovery after conflict or trauma; need to rebuild trust", "Team morale is damaged; recovering from a difficult phase", "High-performance mode; team needs clear direction and accountability"), listOf("Democratic/Participative", "Builds consensus; seeks input from all; decisions reflect the group", "Team buy-in is critical; diverse expertise should inform the decision", "Decision requires team commitment; planning phase", "Emergency; team is inexperienced; decision requires expertise the team lacks"), listOf("Pacesetting", "Sets high standards and leads by personal example; expects self-directed excellence", "High-performing self-motivated team; short-term sprint; clear goal", "Highly skilled team; team is self-directed; clear deadline and goal", "Team needs development; creates burnout if sustained; reduces psychological safety"), listOf("Commanding/Coercive", "Gives direct orders; expects immediate compliance; provides clear direction", "Genuine crisis; safety emergency; turnaround requiring immediate change", "Emergency; safety issue; PM must make a unilateral decision fast", "Normal operations — damages morale, initiative, and psychological safety if overused"), listOf("Laissez-faire", "Hands-off; gives complete autonomy; minimal direction", "Highly expert, self-directed team working on their area of mastery", "Team of experts who need no direction and have proven track record", "New team; team lacking skills; ambiguous situation; abdication disguised as trust"), listOf("Servant Leadership", "Leader exists to serve the team; removes obstacles; empowers; listens", "Agile/high-performing teams; building psychological safety; long-term team health", "Scrum Master role; building trust; empowering the team", "Crisis requiring top-down control; new team needing structure and direction"), listOf("Transformational", "Inspires change; challenges team to exceed limits; paints a compelling future", "Large-scale change initiatives; innovation projects; rebuilding culture", "Organisational change; large strategic project; need to inspire commitment beyond compliance", "Routine operations; team needs stability and predictability"), listOf("Transactional", "Manages by exchange: rewards for performance, consequences for non-performance", "Clear performance criteria; routine work; short-term engagements", "Performance management; contractor management; routine delivery", "Creative work; building intrinsic motivation; long-term team development"))),
                s("Power Types — Complete Reference with Examples", tableHeaders = listOf("Power Type", "Source", "Example", "PMI Assessment", "Exam Application"), tableRows = listOf(listOf("Expert Power", "Knowledge, skills, and expertise that others value and respect", "The PM is the only one who understands the regulatory framework, so team follows their guidance", "MOST effective — earned, respected, intrinsic", "When you have it, leverage it. When you lack it, build it."), listOf("Referent Power", "Personal charisma, trust, respect, and admiration — people follow because they want to", "Team members voluntarily go above and beyond because they believe in the PM as a person", "SECOND most effective — earned through relationship and character", "Takes time to build; cannot be forced; lost through dishonesty"), listOf("Reward Power", "Ability to provide positive consequences (bonuses, recognition, opportunities, good assignments)", "PM can give team members preferred project roles or recommend them for awards", "Moderate effectiveness — motivates but may create transactional relationships", "Use positive reinforcement; avoid creating dependency on external rewards"), listOf("Legitimate Power", "Formal authority conferred by title, position, or organisational hierarchy", "The charter makes the PM the authority on decisions within defined parameters", "Limited effectiveness alone — title without expertise or relationship creates resistance", "Necessary baseline but insufficient for complex stakeholder environments"), listOf("Referent Power (Positional)", "Association with a powerful person or group", "PM is perceived as representing the CEO's office on a strategic project", "Derived — can be lost if the association changes", "Useful but fragile; not a substitute for personal power"), listOf("Informational Power", "Control over information others need", "PM is the central hub for project information; controls what is shared and when", "Effective but creates dependency; ethical concerns about withholding", "Share information proactively — hoarding information creates politics, not power"), listOf("Coercive/Penalty Power", "Ability to impose negative consequences (disciplinary action, negative reviews, removal)", "PM can recommend a team member be removed from the project", "LEAST effective — creates fear, resentment, compliance without commitment", "Never the first tool. Reserve for genuine ethical violations. Destroys psychological safety if used routinely."))),
                s("Power Types — Complete Reference with Examples", "Preferred order (PMI): Expert → Referent → Reward → Legitimate → Coercive (last resort). The exam almost always expects the PM to use the first two. Any option involving coercive power as a first step is almost always wrong.", SectionKind.KEY),
                s("Motivation — All Theories Compared", tableHeaders = listOf("Theory", "Key Concept", "What Motivates", "Exam Application"), tableRows = listOf(listOf("Maslow's Hierarchy", "Needs are hierarchical — lower must be met before higher motivate", "Physiological → Safety → Social → Esteem → Self-Actualisation", "If a lower need is unmet (salary, safety), higher-level motivators (recognition, growth) will not work. Identify which level the person is at."), listOf("Herzberg Two-Factor", "Two separate dimensions: Hygiene factors (prevent dissatisfaction) vs Motivators (create satisfaction)", "Hygiene: salary, security, working conditions. Motivators: achievement, recognition, growth, responsibility, meaningful work", "Improving hygiene removes dissatisfaction but does not create motivation. Must address BOTH dimensions."), listOf("McClelland's Needs", "Three dominant needs vary by individual: Achievement, Affiliation, Power", "High Achievement: challenging goals, feedback, independence. High Affiliation: collaboration, relationships. High Power: leadership, influence.", "Identify dominant need; match the role/assignment to what motivates that person."), listOf("McGregor X/Y", "Two assumptions about human nature: Theory X (people avoid work) vs Theory Y (people seek meaningful work)", "Theory X: controlled, supervised, directed. Theory Y: autonomous, trusted, purposeful", "PMI aligns with Theory Y. Answers that micromanage or assume workers are lazy are Theory X and usually wrong."), listOf("Vroom's Expectancy Theory", "Motivation = Expectancy × Instrumentality × Valence", "E: I can achieve this. I: Performance leads to reward. V: The reward is valuable to me.", "If any factor is zero, motivation is zero. Ensure team believes the goal is achievable, the reward is real, and the reward is desirable."), listOf("Pink's Self-Determination", "Three intrinsic drivers for knowledge work: Autonomy, Mastery, Purpose", "Autonomy: control over HOW you work. Mastery: getting better at something that matters. Purpose: contributing to something larger.", "Traditional \"carrot and stick\" (pay more, threaten more) reduces motivation for complex creative work. Design roles with AMPurpose."), listOf("Ouchi's Theory Z", "Long-term employment, collective decision-making, individual responsibility, holistic concern for employees", "Job security, participative management, team belonging, work-life balance", "Japanese management model. Relevant for questions about long-term team culture and employee retention."))),
                s("Virtual Team Management — Complete Framework", tableHeaders = listOf("Challenge", "Root Cause", "Solutions", "PM Responsibility"), tableRows = listOf(listOf("Isolation", "Physical separation prevents informal connection", "Virtual coffee breaks; online team channels; peer-pairing; buddy system", "Intentionally create informal connection moments — they do not happen naturally"), listOf("Communication Lag", "Time zone differences; async communication misses nuance", "Establish overlap hours; define async communication norms; use video for complex topics", "Set clear communication response-time expectations; do not email at 11 PM and expect morning replies"), listOf("Trust Deficit", "Cannot see team members working; harder to build relationships virtually", "Early face-to-face (even virtual); transparency about workload; celebrate wins publicly", "Model transparency and trust — assume good intent; judge by output not hours"), listOf("Coordination Failures", "No casual hallway coordination; dependencies misunderstood", "Clear task ownership (RACI); explicit handoff protocols; shared project management tools visible to all", "Over-document decisions and action items — written record replaces hallway conversations"), listOf("Cultural Misunderstandings", "High-context vs low-context communication; different norms for directness, hierarchy, time", "Cultural awareness training; explicit team norms in team charter; patience and curiosity", "Create the team charter specifically addressing cross-cultural working norms"), listOf("Technology Barriers", "Different access, skill levels, or tools across locations", "Standardise tools; provide training; ensure all members have equivalent access", "Do not assume tech access — verify before the project starts"), listOf("Meeting Fatigue", "Too many video calls to compensate for lack of in-person interaction", "Async-first culture; short focused meetings; clear agendas; end on time", "Protect team time — evaluate every meeting: could this be an email or async update?"))),
            )
        ),
        Chapter(
            "people-advanced",
            "🧩 Advanced People Skills — Servant Leadership, TKI & Psychological Safety",
            "Servant Leadership · Thomas-Kilmann TKI · Psychological Safety · EI · NVC",
            "People domain",
            listOf(
                s("Key", "People is 33% of the exam — roughly 59 questions. Almost none are definitional; they are scenarios testing judgment. This section gives you the frameworks behind the judgment.", SectionKind.KEY),
                s("Servant Leadership — Advanced Practice", "Servant leadership is PMI's preferred model. Greenleaf's original test: \"Do those served grow as persons? Do they become healthier, wiser, freer, more autonomous, more likely themselves to become servants?\""),
                s("Servant Leadership — Advanced Practice", tableHeaders = listOf("Characteristic", "What the Servant Leader Does", "Anti-Pattern"), tableRows = listOf(listOf("Listening", "Seeks to hear and understand before responding; listens to what is unsaid", "Waits for their turn to talk; interrupts"), listOf("Empathy", "Assumes good intent; understands others' perspectives and constraints", "Judges; assumes laziness or incompetence"), listOf("Healing", "Helps team members recover from setbacks, conflict, and failure", "Assigns blame; \"moves on\" without addressing damage"), listOf("Awareness", "Self-aware and situationally aware; understands ethics, power, values", "Oblivious to team mood, politics, or own impact"), listOf("Persuasion", "Convinces rather than coerces; builds consensus", "Uses positional authority: \"because I said so\""), listOf("Conceptualisation", "Thinks beyond day-to-day; nurtures vision", "Purely tactical; no sense of purpose"), listOf("Foresight", "Learns from the past; understands the present; anticipates consequences", "Reactive; surprised by predictable events"), listOf("Stewardship", "Holds the team, organisation, and resources in trust for others", "Treats the team as a means to personal advancement"), listOf("Commitment to growth", "Invests in every person's development", "Only develops \"high potentials\"; neglects others"), listOf("Building community", "Creates belonging and shared identity", "Pits people against each other; tolerates cliques"))),
                s("Servant Leader Behaviours in Agile Contexts", tableHeaders = listOf("Situation", "Servant Leader Response"), tableRows = listOf(listOf("Team blocked by another department", "Personally removes the impediment; does not delegate the escalation back to the team"), listOf("Team makes a technical decision the PM disagrees with", "Voices concern once, then supports the team's decision (unless safety/ethics)"), listOf("Stakeholder interrupts developers mid-sprint", "Shields the team; redirects the stakeholder to the PO / next sprint review"), listOf("Team member struggling", "Coaches privately; asks what support they need; never exposes them publicly"), listOf("Team succeeds", "Credits the team publicly; takes no personal credit"), listOf("Team fails", "Takes accountability publicly; analyses privately with the team without blame"), listOf("Team wants to try a new practice", "Enables the experiment; helps measure results; supports even if it fails"))),
                s("Thomas-Kilmann Conflict Mode Instrument (TKI)", "TKI maps five conflict modes on two axes: Assertiveness (concern for own goals) and Cooperativeness (concern for others' goals). Every mode has a place — the skill is choosing the right one."),
                s("Thomas-Kilmann Conflict Mode Instrument (TKI)", tableHeaders = listOf("Mode", "Assertive?", "Cooperative?", "Description", "Use When", "Avoid When"), tableRows = listOf(listOf("Competing (Forcing)", "High", "Low", "Win-lose; pursue own goals at others' expense", "Emergency; safety; unpopular but necessary decision; protecting against exploitation", "Relationship matters; you may be wrong; long-term collaboration needed"), listOf("Collaborating", "High", "High", "Win-win; work together to find a solution satisfying everyone", "Both sets of concerns are important; need buy-in; merge insights; build relationship", "Time-critical; issue trivial; other party acting in bad faith"), listOf("Compromising", "Medium", "Medium", "Split the difference; each side gives something", "Goals moderately important; equal power; temporary settlement; time pressure", "Would sacrifice a critical principle; a better solution exists via collaboration"), listOf("Avoiding", "Low", "Low", "Sidestep; postpone; withdraw", "Issue trivial; no chance of winning; cooling-off needed; others can resolve better", "Issue is important; decision needed now; avoidance breeds resentment"), listOf("Accommodating", "Low", "High", "Yield; satisfy others' concerns at expense of own", "You are wrong; issue matters more to them; preserve harmony; build goodwill for later", "Issue is important to you; sets a precedent of being exploited"))),
                s("Thomas-Kilmann Conflict Mode Instrument (TKI)", "PMI's default: Collaborating is preferred; Avoiding is least preferred. But the exam tests SITUATIONAL judgment — in a genuine safety emergency, Competing is correct. In a trivial dispute where tempers are high, Avoiding (temporarily) may be correct.", SectionKind.WARN),
                s("TKI vs. PMBOK Conflict Techniques — Mapping", tableHeaders = listOf("TKI Mode", "PMBOK Term", "Same Thing?"), tableRows = listOf(listOf("Collaborating", "Collaborate / Problem Solve", "Yes"), listOf("Compromising", "Compromise / Reconcile", "Yes"), listOf("Accommodating", "Smooth / Accommodate", "Yes"), listOf("Competing", "Force / Direct", "Yes"), listOf("Avoiding", "Withdraw / Avoid", "Yes"))),
                s("Sources of Conflict on Projects (in order of frequency)", "• Schedules — the #1 source; conflicting priorities and deadlines\n• Project priorities — disagreement over what matters most\n• Resources — competition for people, equipment, budget\n• Technical opinions — disagreement over approach\n• Administrative procedures — how things get done\n• Cost — budget disputes\n• Personalities — the LEAST frequent source, despite popular belief"),
                s("Sources of Conflict on Projects (in order of frequency)", "Exam trap: personality clashes are the LEAST common cause of project conflict. Schedules are the MOST common. If a question asks \"what is the most likely source of this conflict?\" — think schedule, not personality.", SectionKind.TIP),
                s("Psychological Safety — Amy Edmondson's Framework", "Psychological safety is the shared belief that the team is safe for interpersonal risk-taking — speaking up, asking questions, admitting mistakes, and disagreeing without fear of punishment or humiliation. Google's Project Aristotle found it the #1 predictor of team effectiveness."),
                s("Psychological Safety — Amy Edmondson's Framework", tableHeaders = listOf("Level", "Description", "Signs"), tableRows = listOf(listOf("1. Inclusion Safety", "I feel accepted as a member of the team", "People are greeted, included in conversations, not ignored"), listOf("2. Learner Safety", "I can ask questions, experiment, and make mistakes", "People ask \"dumb\" questions; mistakes discussed openly"), listOf("3. Contributor Safety", "I can contribute ideas and use my skills", "People volunteer ideas; quiet members speak in meetings"), listOf("4. Challenger Safety", "I can challenge the status quo and disagree with leaders", "People say \"I think we are wrong about this\" to the PM"))),
                s("How the PM Builds Psychological Safety", tableHeaders = listOf("Practice", "Example"), tableRows = listOf(listOf("Frame work as learning", "\"This is complex — we will make mistakes, and that is how we learn\""), listOf("Acknowledge own fallibility", "\"I may have missed something here — what do you see?\""), listOf("Model curiosity", "Ask questions; ask for dissent: \"Who sees this differently?\""), listOf("Respond productively to bad news", "Thank the messenger; focus on the problem, not the person"), listOf("Blameless post-mortems", "Analyse failures for system causes, not individual fault"), listOf("Protect dissenters", "Publicly value the person who raised the concern, even if it turns out unfounded"), listOf("Consistent boundaries", "Safety is not permissiveness — unethical or abusive behaviour is still addressed"))),
                s("Signs Psychological Safety Is LOW", "• Meetings are silent; only the PM and one or two seniors speak\n• Problems surface late — people hide bad news until it is undeniable\n• Status is always \"green\" until suddenly \"red\"\n• Mistakes are hidden or blamed on others\n• No one challenges obviously flawed plans\n• High turnover; disengagement; \"quiet quitting\""),
                s("Signs Psychological Safety Is LOW", "The team that misreported status to hide delays (from the Mindset quiz) is a psychological safety failure. The PM's job is not only to fix the report but to fix the environment that made people afraid to report honestly.", SectionKind.KEY),
                s("Emotional Intelligence — Applied Techniques", tableHeaders = listOf("Technique", "How", "When"), tableRows = listOf(listOf("Active Listening", "Full attention; paraphrase; reflect feelings; ask clarifying questions; do not interrupt", "Every stakeholder conversation; especially conflict"), listOf("Naming the emotion", "\"It sounds like you are frustrated that the timeline moved again\"", "De-escalation; showing empathy"), listOf("The pause", "Take a breath before responding to provocation", "When you feel a strong reaction"), listOf("Perspective-taking", "\"If I were in their role, what would I be worried about?\"", "Before negotiating or delivering bad news"), listOf("Non-violent communication (NVC)", "Observation → Feeling → Need → Request. \"When the report was late (observation), I felt concerned (feeling) because the sponsor needs it for the board (need). Could you let me know earlier next time if it will slip? (request)\"", "Giving feedback without blame"), listOf("Reading the room", "Notice body language, silence, side conversations, energy level", "Meetings; retrospectives"), listOf("Regulating others", "Calm tone, slower pace, acknowledge, redirect to problem-solving", "Heated meetings"))),
                s("Influencing Without Authority", "Most PMs (especially in matrix organisations) have responsibility without authority. Influence techniques:"),
                s("Influencing Without Authority", tableHeaders = listOf("Technique", "Description"), tableRows = listOf(listOf("Reciprocity", "Help others first; build a bank of goodwill"), listOf("Social proof", "\"Three other teams have adopted this and seen results\""), listOf("Expert power", "Demonstrate competence; be the person people ask"), listOf("Framing in their interest", "Explain how the request helps THEIR goals"), listOf("Coalition building", "Align supporters before the meeting; avoid ambushes"), listOf("Consistency", "Small commitments lead to larger ones"), listOf("Transparency", "Share data and reasoning; invite challenge"))),
                s("Motivating Knowledge Workers — Daniel Pink's Model", tableHeaders = listOf("Driver", "Definition", "PM Application"), tableRows = listOf(listOf("Autonomy", "Desire to direct our own lives and work", "Let the team decide HOW; define WHAT and WHY"), listOf("Mastery", "Urge to get better at something that matters", "Provide challenging work; learning time; feedback"), listOf("Purpose", "Yearning to contribute to something larger than ourselves", "Connect work to outcomes and impact; share the vision"))),
                s("Motivating Knowledge Workers — Daniel Pink's Model", "Pink's research: for complex, creative work, carrot-and-stick rewards (bonuses, penalties) can REDUCE performance. Autonomy, mastery, and purpose drive knowledge workers — aligning with Herzberg's motivators and McGregor's Theory Y.", SectionKind.TIP),
                s("Worked example — 📖 Worked Example: TKI in a Real Sprint", "Situation: It is Sprint 4, Day 7. Two senior developers — Ankur (backend) and Neha (frontend) — have been in a 90-minute Zoom call arguing about whether the API should return paginated results or all records at once. The rest of the team is waiting. The sprint ends in 3 days.\n\nOption 1 — Avoid (Wrong):\n\nScrum Master says \"OK let's let you both think about it and discuss tomorrow.\" → Day 8: still no decision. Day 9: sprint fails. This is Withdrawing/Avoiding — the worst choice here.\n\nOption 2 — Compete/Force (Situationally justified):\n\nWith 3 days left and a clear technical answer available, the Scrum Master or tech lead makes the call: \"We use paginated results. Here is why: mobile network constraints, memory management on client side. Document your concerns in a retrospective item.\" This is competing — appropriate here because time is critical and the decision can be documented for future review.\n\nOption 3 — Collaborate (Best if time permits):\n\nIf it is Day 3 of the sprint: \"Let's spend 30 minutes agreeing on the decision criteria — what are we optimising for: load time, mobile performance, or server cost? Then we let the criteria decide.\" This is collaborating — produces the best outcome and builds team consensus for future decisions.\n\nOption 4 — Compromise:\n\n\"Paginated for mobile; full results for desktop API?\" — each side gives something. Not ideal technically, but resolves the conflict.\n\nThe lesson: PMI prefers Collaborate. But the exam tests SITUATIONAL judgment. In a time emergency → Compete. When both parties are equal and time allows → Collaborate. When relationship matters more than outcome → Compromise or Accommodate.", SectionKind.TIP),
                s("Worked example — 📖 Worked Example: Building Psychological Safety — Before and After", "BEFORE (Low Psychological Safety team):\n\nSprint 7 review. PM asks \"Any concerns about the payment gateway integration timeline?\"\n\n[Silence. Dev 2 knows there is a serious dependency issue but says nothing because the last time he raised a concern, the PM said \"that is not your problem to solve — just write the code.\"]\n\nDay 11 of Sprint 8: Dev 2 finally cannot hide it. The gateway has a 6-week vendor certification process that nobody planned for. Sprint fails. Sponsor furious. PM wonders \"why did nobody raise this earlier?\"\n\nAFTER (PM rebuilds Psychological Safety over 3 sprints):\n\nPM actions taken:\n\n1. In Sprint Planning, PM opens: \"Last sprint I missed some signals. If anyone has concerns this sprint — even half-formed ones — I want to hear them. There are no dumb concerns.\"\n\n2. In Daily Scrum, PM models vulnerability: \"I realised I hadn't mapped the vendor certification timeline. My oversight. Let us fix it together.\"\n\n3. When Dev 3 tentatively raises a concern about the auth token expiry, PM says: \"That is exactly the kind of thing I need to hear. Thank you, Priya. Let's investigate.\"\n\n4. In retrospective, PM asks: \"What would make it easier for people to raise concerns earlier?\"\n\nSprint 10 result:\n\nDev 2 raises the gateway certification issue in Sprint Planning — 3 weeks before it would have been a crisis. Team adjusts the plan. Sprint succeeds. PM thanks Dev 2 publicly.\n\nThe principle: Psychological safety is not built by saying \"please feel safe.\" It is built by demonstrating — repeatedly — that speaking up leads to a better outcome than silence.", SectionKind.TIP),
                s("Worked example — 📖 Worked Example: Non-Violent Communication (NVC) in Feedback", "Situation: A team member, Rohan, submitted code without running tests. The code went to production and caused a 20-minute outage. This is the second time this month.\n\nTraditional (blame-based) approach:\n\n\"Rohan, how could you do this again? You know the rules. This is completely unacceptable. You need to take this seriously.\"\n\n→ Result: Rohan is defensive, embarrassed, disengaged. Does not understand what to change. Psychological safety damaged for the whole team.\n\nNVC approach:\n\nObservation: \"Rohan, in the last two deployments, tests were not run before pushing to production.\"\n\nFeeling: \"I am concerned, because production incidents affect our customers and our team's credibility.\"\n\nNeed: \"I need every deployment to go through the test gate — it is there to protect the product and the team.\"\n\nRequest: \"Can you walk me through what happened both times? I want to understand if there is a process issue, a tool issue, or something I can help you with.\"\n\nResult: Rohan explains that the CI/CD pipeline on his branch was broken and he did not know how to fix it. He was afraid to ask because he thought it would reflect badly. The PM helps fix the pipeline and adds a \"broken pipeline\" alert. Problem solved at root cause — not just symptoms.\n\nThe lesson: NVC (Observation → Feeling → Need → Request) addresses the BEHAVIOUR without attacking the PERSON. It creates the conditions for honest conversation. It is not weakness — it produces better outcomes.", SectionKind.TIP),
            )
        ),
        Chapter(
            "ethics",
            "⚖️ PMI Code of Ethics & Professional Conduct",
            "PMI Code · 4 Values · EDMF Framework · Conflict of Interest · Ethics in AI",
            "People domain",
            listOf(
                s("Danger", "Ethics is not a separate exam domain — it is woven through ALL three domains, especially People (33%) and Business Environment (26%). Situational questions constantly test whether you will choose integrity over convenience.", SectionKind.DANGER),
                s("The Four Values — Aspirational and Mandatory Standards", "Each value has aspirational standards (what we strive for) and mandatory standards (firm requirements — violations can result in disciplinary action by PMI)."),
                s("1. Responsibility", tableHeaders = listOf("Aspirational", "Mandatory"), tableRows = listOf(listOf("Make decisions based on the best interests of society, public safety, and the environment", "Inform ourselves of and uphold policies, rules, regulations, and laws governing our work"), listOf("Accept only assignments consistent with our background, experience, skills, and qualifications", "Report unethical or illegal conduct to appropriate management and, if necessary, to those affected"), listOf("Fulfil commitments we undertake — we do what we say we will do", "Bring violations of the Code to PMI's attention; only file complaints substantiated by facts"), listOf("Take ownership of errors and make corrections promptly", "Pursue disciplinary action against anyone who retaliates against a person raising ethics concerns"))),
                s("2. Respect", tableHeaders = listOf("Aspirational", "Mandatory"), tableRows = listOf(listOf("Inform ourselves about norms and customs of others; avoid behaviour they may consider disrespectful", "Negotiate in good faith"), listOf("Listen to others' points of view; seek to understand them", "Do not exercise power of expertise or position to influence decisions for personal benefit at others' expense"), listOf("Approach directly those with whom we have a conflict or disagreement", "Do not act in an abusive manner toward others"), listOf("Conduct ourselves professionally, even when it is not reciprocated", "Respect the property rights of others"))),
                s("3. Fairness", tableHeaders = listOf("Aspirational", "Mandatory"), tableRows = listOf(listOf("Demonstrate transparency in our decision-making process", "Proactively and fully disclose any real or potential conflicts of interest"), listOf("Constantly re-examine impartiality and objectivity; take corrective action as appropriate", "When a conflict of interest exists, refrain from participating in decisions until fully disclosed and stakeholders consent to proceed"), listOf("Provide equal access to information to those authorised to have it", "Do not hire, fire, reward, or punish based on personal considerations (favouritism, nepotism, bribery)"), listOf("Make opportunities equally available to qualified candidates", "Do not discriminate on gender, race, age, religion, disability, nationality, or sexual orientation"))),
                s("4. Honesty", tableHeaders = listOf("Aspirational", "Mandatory"), tableRows = listOf(listOf("Earnestly seek to understand the truth", "Do not engage in or condone behaviour designed to deceive others — false statements, half-truths, information out of context, withholding information"), listOf("Be truthful in our communications and conduct", "Do not engage in dishonest behaviour with the intention of personal gain or at the expense of another"), listOf("Provide accurate information in a timely manner", "—"), listOf("Make commitments and promises in good faith", "—"), listOf("Create an environment where others feel safe to tell the truth", "—"))),
                s("4. Honesty", "Memory hook: R-R-F-H → \"Really Respect Fair Honesty.\" Responsibility · Respect · Fairness · Honesty.", SectionKind.TIP),
                s("Ethical Decision-Making Framework (PMI EDMF)", "PMI publishes a five-step Ethical Decision-Making Framework. When a question describes an ethical dilemma, walk through these steps:\n\n1. Assessment→2. Alternatives→3. Analysis→4. Application→5. Action"),
                s("Ethical Decision-Making Framework (PMI EDMF)", tableHeaders = listOf("Step", "What You Do", "Key Questions"), tableRows = listOf(listOf("1. Assessment", "Ensure you have all the facts about the ethical dilemma", "What are the facts? Is it legal? Does it violate the Code? Who is affected?"), listOf("2. Alternatives", "Consider your choices — including the option of doing nothing", "What are ALL the options? What are the consequences of each?"), listOf("3. Analysis", "Identify the candidate decision and test its validity", "Does it uphold all four values? Would I be comfortable if it were public? Does it treat everyone fairly?"), listOf("4. Application", "Apply ethical principles to the candidate decision", "Is it consistent with PMI values? Organisational values? Cultural context (without compromising the Code)?"), listOf("5. Action", "Make the decision and take responsibility for it", "Document the decision. Communicate to affected parties. Own the outcome."))),
                s("Conflict of Interest — Detailed", tableHeaders = listOf("Situation", "Is It a Conflict?", "Correct Action"), tableRows = listOf(listOf("Your brother-in-law's company is bidding on your project", "Yes — personal relationship with a bidder", "Disclose immediately in writing; recuse from evaluation and selection"), listOf("You own shares in a vendor being considered", "Yes — financial interest", "Disclose; recuse from decision; consider divesting if material"), listOf("A vendor offers you a paid speaking engagement during evaluation", "Yes — potential inducement", "Decline until procurement is complete; disclose the offer"), listOf("Your previous employer is a bidder", "Potential — perceived bias", "Disclose; let stakeholders decide whether you should participate"), listOf("You are asked to evaluate a proposal from a company where you interviewed last year", "Potential — perceived interest", "Disclose; typically fine to proceed if stakeholders consent"), listOf("A team member reports to you AND is your close friend", "Potential — favouritism risk", "Disclose to your manager; ensure evaluations are objective and documented"))),
                s("Conflict of Interest — Detailed", "The test is not just ACTUAL conflict — it is also PERCEIVED conflict. If a reasonable observer might think your judgment is compromised, disclose it. When in doubt, disclose.", SectionKind.KEY),
                s("Professional Responsibility Scenarios — Full Reference", tableHeaders = listOf("Scenario", "Wrong Response", "Right Response"), tableRows = listOf(listOf("Sponsor tells you to report \"green\" status when project is \"red\"", "Comply to keep the sponsor happy", "Refuse; report accurately; explain that misreporting harms decision-making and violates Honesty"), listOf("You discover a colleague falsifying safety test results", "Confront them privately and let it go if they promise to stop", "Report through appropriate channels — public safety is at stake (Responsibility)"), listOf("A team member from another culture greets you in a way you find odd", "Correct their behaviour", "Inform yourself about their norms; adapt (Respect)"), listOf("You are offered a project you are not qualified for", "Accept — it is a great career move", "Decline or seek support/training first (Responsibility — accept only qualified assignments)"), listOf("Local custom requires \"facilitation payments\" to get permits", "Pay — \"when in Rome\"", "Do not pay bribes regardless of local custom (Fairness/Honesty; also usually illegal under FCPA/UK Bribery Act)"), listOf("A stakeholder asks you to share confidential bid information with a preferred vendor", "Share — the stakeholder has authority", "Refuse — equal access to information (Fairness)"), listOf("You made an estimation error costing the project \$50K", "Blame the data you were given", "Own the error; propose recovery plan (Responsibility)"), listOf("A team member is being bullied by another", "Stay out of it — not your business", "Intervene; address the abusive behaviour (Respect — mandatory standard)"), listOf("You learn of a PMI Code violation by another PMP", "Ignore — not your role to police", "Report to PMI if substantiated by facts (Responsibility — mandatory)"), listOf("A contractor offers a small gift at project completion", "Accept — the project is done", "Check organisational policy; modest gifts after completion are often acceptable, but disclose"))),
                s("Ethics in the Age of AI (2026)", "• Transparency: Disclose when AI has been used to generate project artifacts, estimates, or reports\n• Accountability: The PM remains accountable for AI-generated outputs — \"the AI did it\" is never a defence\n• Bias: AI models can encode bias; PMs must check AI recommendations for fairness (e.g., in resource allocation, vendor selection)\n• Data privacy: Do not feed confidential project or personal data into external AI tools without authorisation\n• Honesty: Do not present AI-generated content as human expert judgment\n• Intellectual property: Respect IP rights in AI training data and outputs"),
                s("Worked example — 📖 Worked Example: Applying All Four PMI Values in One Decision", "Situation: You are PM for a ₹15 crore ERP implementation at a manufacturing company. Week 8: your vendor's on-site consultant privately tells you that a junior team member from the client side has been sharing confidential implementation plans with a competitor who is bidding for Phase 2. You cannot prove it — it is the consultant's word.\n\nApplying each PMI value:\n\nResponsibility:\n\nYou cannot ignore this. Responsibility (mandatory): report unethical or illegal conduct to appropriate management. BUT — you must act on facts, not rumour. Responsibility also means \"only bring complaints based on facts.\" Do not accuse without evidence.\n\n→ Action: Document what the consultant told you verbatim, with date and time.\n\nRespect:\n\nThe accused team member is innocent until there is evidence. You cannot confront them, exclude them, or treat them as guilty.\n\n→ Action: Do not change the team member's access or responsibilities yet. Do not discuss with others.\n\nFairness:\n\nYou have an obligation to the client organisation — they are trusting you with their confidential implementation data. You also cannot let an unsubstantiated accusation destroy a junior employee's career.\n\n→ Action: Report to the client's senior sponsor and suggest an internal investigation process — not your own investigation.\n\nHonesty:\n\nYou must be truthful about what you know and what you do not know. Do not overstate or understate the situation.\n\n→ Action: \"A vendor team member has reported to me a concern about potential information leakage. I cannot verify it. I am bringing it to your attention because it involves your organisational security. I recommend you engage HR and security to investigate.\"\n\nResult: You act with all four values simultaneously. You report (Responsibility). You do not accuse (Respect + Fairness). You are transparent about the uncertainty (Honesty). The investigation is not yours to conduct — it is the client's.", SectionKind.TIP),
                s("Worked example — 📖 Worked Example: Conflict of Interest — Three Levels", "Level 1 — Clear and Obvious:\n\nYour brother's company is bidding for a vendor contract on your project. This is a clear conflict of interest.\n\n→ Disclose in writing immediately. Recuse yourself from the evaluation. Let someone else lead the vendor selection. Do not even review the proposals.\n\nLevel 2 — Subtle but Real:\n\nYou interviewed for a job at Vendor B three months ago. They are now shortlisted for a ₹2 crore contract. You did not get the job offer.\n\n→ Still a conflict. Disclose to your manager: \"I had discussions about employment with Vendor B in [month]. I want to ensure there is no perceived bias in my evaluation.\" Ask your manager if you should recuse or if full disclosure is sufficient. Let them decide.\n\nLevel 3 — Perceived but Not Actual:\n\nYour spouse works in the accounts department of a company that is in the same industry as a bidding vendor, but has no connection to the bid.\n\n→ Probably no conflict, but consider disclosing anyway. The test: would a reasonable observer think your judgment might be influenced? If yes → disclose. If no reasonable person would think so → use judgment. When in doubt, disclose.\n\nThe PMI rule: Fairness (mandatory standard): \"Proactively and FULLY disclose any real or POTENTIAL conflicts of interest.\" The word \"potential\" is key — you do not wait until there is an actual problem. Disclose early, transparently, in writing.\n\nExam trap: \"The PM's friend is a senior employee at the bidding vendor. The PM evaluates fairly and the friend's company wins on merit. Is this acceptable?\"\n\n→ NO. Even if the decision was fair, the PROCESS was compromised by the undisclosed relationship. The mandatory standard requires disclosure regardless of the actual outcome.", SectionKind.TIP),
            )
        ),
        Chapter(
            "business",
            "🏢 Business Environment (8% of Exam)",
            "Portfolio/Program/Project · Org Structures · PMO Types · ADKAR · Benefits",
            "Business & tailoring",
            listOf(
                s("Note", "26% of the exam in 2026 ECO — Business Environment tripled from 8% to 26%. These questions now carry significant weight and cover governance, compliance, AI, sustainability, and strategy. Do NOT treat as minor. and conceptual. Do not ignore them — they are usually straightforward if you know the theory.", SectionKind.NOTE),
                s("Portfolio, Programs, and Projects — Hierarchy", tableHeaders = listOf("Level", "Definition", "Managed By", "Success Measured By"), tableRows = listOf(listOf("Portfolio", "Projects, programs, subsidiary portfolios, and operations managed as a group to achieve STRATEGIC objectives", "Portfolio Manager / Executive", "Strategic alignment; maximised return on investment; right mix of initiatives"), listOf("Program", "Related projects managed in a coordinated manner to obtain BENEFITS not available from managing them individually", "Program Manager", "Benefits realisation beyond individual projects; synergies achieved"), listOf("Project", "Temporary endeavour to create a unique product, service, or result with a definitive beginning and end", "Project Manager", "On time, on budget, scope met, quality achieved, value delivered"), listOf("Operations", "Ongoing, repetitive activities that produce the same result repeatedly", "Operations Manager", "Efficiency, productivity, continuous quality improvement"))),
                s("Organisational Structures — PM Authority Levels", tableHeaders = listOf("Structure", "PM Authority", "PM Time Commitment", "Resource Availability", "Who Controls Resources?"), tableRows = listOf(listOf("Organic / Simple", "Little or none", "Part-time", "Little or none", "Owner or Operator"), listOf("Functional", "Little or none", "Part-time", "Little or none", "Functional Manager — PM has no authority"), listOf("Matrix — Weak", "Low", "Part-time", "Low", "Functional Manager dominant"), listOf("Matrix — Balanced", "Low to Moderate", "Part-time", "Low to Moderate", "Shared between PM and Functional Manager"), listOf("Matrix — Strong", "Moderate to High", "Full-time", "Moderate to High", "PM dominant"), listOf("Project-Oriented (Projectised)", "High to Almost Total", "Full-time", "High to Almost Total", "Project Manager controls"), listOf("PMO Structure", "High to Almost Total", "Full-time", "High", "PMO / Project Manager"))),
                s("Organisational Structures — PM Authority Levels", "The more PROJECT-ORIENTED the structure, the MORE authority the PM has. In a functional org, the PM has almost no authority — everything goes through the Functional Manager. This creates the classic \"PM with responsibility but no authority\" challenge.", SectionKind.WARN),
                s("PMO Types — Know All Three", tableHeaders = listOf("PMO Type", "Control Level", "Role", "Exam Tip"), tableRows = listOf(listOf("Supportive", "Low — consultative", "Repository of templates, best practices, training, lessons learned. Projects can use or ignore.", "PM has the most autonomy here"), listOf("Controlling", "Moderate — compliance required", "Requires adoption of frameworks, templates, governance tools, and reporting. Projects must comply.", "PM must follow PMO standards"), listOf("Directive", "High — directly manages", "PMO members ARE the project managers — they take direct control of projects.", "PM works FOR the PMO"))),
                s("EEF vs. OPA — Critical Distinction", "Enterprise Environmental Factors (EEF)\n Conditions NOT under the project team's control that influence, constrain, or direct the project. Can be INTERNAL or EXTERNAL.\n • Organisational culture and structure\n• Government or industry regulations and standards\n• Market conditions and competitive landscape\n• Infrastructure: physical environment, tools, IT systems\n• Commercial databases (published benchmarks, pricing)\n• Geographic distribution of facilities and resources\nOrganisational Process Assets (OPA)\n Plans, processes, policies, procedures, and knowledge bases specific to the organisation. The project team can USE and UPDATE these.\n • Templates, forms, and standardised processes\n• Lessons learned repository from past projects\n• Historical project information and performance data\n• Change control procedures and CCB charter\n• Financial controls and reporting requirements\n• Project management information systems (PMIS)"),
                s("EEF vs. OPA — Critical Distinction", "EEF = the environment you work IN (external constraints you cannot control). OPA = the organisational KNOWLEDGE you can work WITH (internal assets you can use and update). Both are inputs to most planning processes.", SectionKind.TIP),
                s("Benefits Management Plan — Contents", "• Target benefits: Tangible (revenue increase, cost savings) AND intangible (brand reputation, employee satisfaction)\n• Strategic alignment: How the benefits connect to organisational strategy and objectives\n• Timeframe: When benefits will be realised — short-term, long-term, ongoing, or by phase\n• Benefits owner: Who is accountable for monitoring, recording, and reporting benefits realisation\n• Metrics: Direct and indirect measures used to confirm benefits are being realised\n• Assumptions and risks: Factors expected to be in place for benefits to occur, and risks to realisation"),
                s("Governance and Project Governance", "• Organisational governance: Framework, functions, processes that guide strategy and operations at the enterprise level\n• Project governance: Framework for decisions, oversight, and controls specific to the project — aligned to organisational governance\n• Project governance includes: decision-making authority, change control, reporting requirements, acceptance criteria, stage gates\n• PMBOK 8: Governance is a full performance domain — it integrates risk, quality, change, and knowledge management"),
                s("2026 ECO — Business Environment Is Now 26% of the Exam", "The Business Environment domain tripled from 8% to 26% in the 2026 ECO. This is the single biggest change from the 2021 ECO. It now covers 8 tasks across governance, compliance, AI/sustainability, strategy alignment, and external change. Study it as seriously as you study Risk or Schedule."),
                s("2026 ECO — Business Environment Is Now 26% of the Exam", "26% means roughly 46–47 questions are from this domain (out of 180). That is almost as many as the entire People domain. Candidates who treat it as an afterthought will fail.", SectionKind.DANGER),
                s("2026 Business Environment — 8 Tasks to Know", tableHeaders = listOf("#", "Task", "What It Tests"), tableRows = listOf(listOf("1", "Evaluate & Recommend Strategy", "Align project outcomes with organisational strategy; evaluate options against strategic objectives; recommend the best-fit approach"), listOf("2", "Support Organisational Change", "Assess change readiness; plan and support change activities; manage resistance; collaborate with change management teams"), listOf("3", "Manage Compliance Requirements", "Determine compliance categories (legal, regulatory, internal policy); ensure project compliance; take corrective action when non-compliant"), listOf("4", "Evaluate & Deliver Benefits & Value", "Investigate benefit realisation mechanisms; ensure project is delivering intended business value; monitor value throughout"), listOf("5", "Evaluate & Address External Business Environment Changes", "Survey external environment (market, regulatory, political, economic); assess impact on project; update plans accordingly"), listOf("6", "Support Organisational Governance", "Identify and prioritise governance rules and policies; align project with governance framework; escalate governance issues"), listOf("7", "Integrate Project Planning Activities", "Consolidate project plans across all domains; ensure integrated baseline; use outputs from one plan as inputs to others"), listOf("8", "Manage and Implement AI/Technology in the Project Environment", "Evaluate AI tools for PM use; apply AI to planning, risk, and reporting; ensure responsible and ethical AI use; address AI-related risks"))),
                s("AI in Project Management (2026 ECO — New Topic)", "AI is formally part of the Business Environment domain in the 2026 ECO. Expect questions on:"),
                s("AI in Project Management (2026 ECO — New Topic)", tableHeaders = listOf("AI Application", "What the PM Does"), tableRows = listOf(listOf("AI-assisted risk identification", "Use AI tools to scan project data for emerging risks; validate AI outputs with expert judgment"), listOf("AI for schedule optimisation", "Leverage AI to model schedule scenarios; still applies human judgment for final decisions"), listOf("AI in reporting & dashboards", "Use AI to generate real-time performance dashboards; ensure data accuracy and integrity"), listOf("Responsible AI use", "Ensure AI decisions are explainable, fair, unbiased; follow organisational AI policy; document AI usage"), listOf("AI-related risks", "Identify risks of AI adoption (data quality, bias, dependency, regulatory); add to risk register"), listOf("Prompt engineering", "Use AI prompts as a project communication and analysis skill (formalised in PMBOK 8)"))),
                s("AI in Project Management (2026 ECO — New Topic)", "PMI's AI stance: AI augments the PM — it does not replace PM judgment. Always validate AI outputs. Always document AI usage. Ethical and responsible AI is required, not optional.", SectionKind.KEY),
                s("Sustainability in Projects (2026 ECO)", tableHeaders = listOf("Aspect", "What It Means in Practice"), tableRows = listOf(listOf("Environmental", "Assess and minimise carbon footprint, waste, and resource consumption in project activities"), listOf("Social", "Consider community impacts, diversity and inclusion, worker welfare, and stakeholder wellbeing"), listOf("Economic", "Ensure long-term value creation; avoid short-term gains that create long-term organisational or societal costs"), listOf("PM Action", "Include sustainability goals in business case; raise sustainability risks in the risk register; report on sustainability metrics alongside schedule and cost"))),
                s("Benefits Realisation — 2026 Extended Focus", "The 2026 ECO places much greater emphasis on benefits realisation throughout the project and beyond closure:"),
                s("Benefits Realisation — 2026 Extended Focus", tableHeaders = listOf("Phase", "Benefits Activity"), tableRows = listOf(listOf("Initiating", "Business case defines expected benefits; Benefits Management Plan drafted; sponsor confirms benefits ownership"), listOf("Planning", "Benefits metrics and measurement mechanisms defined; benefits realisation timeline established"), listOf("Executing", "Track early benefit signals; ensure deliverables align with intended benefits; communicate benefits progress"), listOf("Closing", "Verify benefits have been or will be realised; transition to operations with benefits tracking in place"), listOf("Post-Project", "Operations team monitors and reports on benefits; PM may support benefits review if engaged"))),
                s("Organisational Change Management (2026 — Expanded)", "Change management is now an explicit Business Environment task. The PM must:"),
                s("Organisational Change Management (2026 — Expanded)", tableHeaders = listOf("Step", "Action"), tableRows = listOf(listOf("Assess Readiness", "Evaluate organisational capacity to absorb the change; identify resistance hotspots"), listOf("Plan Change Activities", "Develop change management approach; coordinate with HR, communications, and leadership teams"), listOf("Manage Resistance", "Identify root causes of resistance; address concerns proactively; build coalitions of support"), listOf("Monitor Adoption", "Track change adoption metrics; adjust approach based on feedback; report adoption status"))),
                s("Organisational Change Management (2026 — Expanded)", "Exam Tip: When a question mentions organisational change — always look for answers that involve assessing readiness FIRST, then planning, then managing resistance. Never jump straight to implementing change.", SectionKind.TIP),
                s("External Environment Monitoring", "The PM must continuously monitor the external environment and adapt the project accordingly:"),
                s("External Environment Monitoring", tableHeaders = listOf("External Factor", "PM Response"), tableRows = listOf(listOf("New legislation or regulation", "Update Risk Register → assess compliance impact → adjust project plans → ensure compliance"), listOf("Market changes", "Re-evaluate business case value → assess impact on project benefits → engage sponsor"), listOf("Political/economic shifts", "Identify risks and opportunities → update risk register → adapt procurement and resource strategies"), listOf("Competitor moves", "Assess strategic relevance of project → engage sponsor → consider scope adjustment if needed"), listOf("Technology disruption", "Evaluate impact on project approach → assess AI/tool adoption opportunities → update tailoring decisions"))),
                s("Business Case — Components", tableHeaders = listOf("Section", "Content"), tableRows = listOf(listOf("Business Need", "What problem or opportunity is being addressed? Why now?"), listOf("Situation Analysis", "Current state; root cause; gap between current and desired state"), listOf("Options Analysis", "Alternative solutions considered (including \"do nothing\")"), listOf("Recommended Solution", "Chosen option with rationale"), listOf("Financial Analysis", "NPV, ROI, payback, BCR, total cost of ownership"), listOf("Risks", "Major risks of proceeding and NOT proceeding"), listOf("Benefits", "Expected tangible and intangible benefits (links to Benefits Management Plan)"), listOf("Success Criteria", "How success will be measured"))),
                s("Business Case — Components", "The Sponsor owns the Business Case. The PM references it throughout the project to ensure the project still delivers the intended value. If the business case becomes invalid — the PM must escalate.", SectionKind.KEY),
                s("Strategic Alignment", "Every project should trace to organisational strategy. The PM must be able to articulate this chain:\n\nOrganisational Vision→Strategic Objectives→Portfolio→Program→Project→Deliverables→Outcomes→Benefits→Value\n\n• Mission: Why the organisation exists\n• Vision: Where the organisation wants to be\n• Strategy: How it will get there\n• Portfolio: The collection of initiatives to execute strategy\n• Project: A single initiative delivering specific outputs toward strategy"),
                s("Compliance Categories", tableHeaders = listOf("Category", "Examples", "PM Responsibility"), tableRows = listOf(listOf("Legal/Regulatory", "Data protection (GDPR), safety (OSHA), industry (FDA, SOX)", "Must comply — no exceptions; add to risk register; audit"), listOf("Organisational Policy", "Procurement rules, security policies, HR policies", "Follow; tailor within policy bounds"), listOf("Contractual", "SLA terms, delivery obligations, IP rights", "Track and report; ensure vendor compliance too"), listOf("Standards", "ISO 9001, PMI standards, industry standards", "Apply where required or beneficial"), listOf("Ethical", "PMI Code of Ethics", "Always applies regardless of local practice"), listOf("Sustainability", "ESG reporting, environmental regulations (new in 2026)", "Report and manage sustainability compliance"))),
                s("Organisational Change Management Models", tableHeaders = listOf("Model", "Steps / Concept", "Use"), tableRows = listOf(listOf("ADKAR", "Awareness → Desire → Knowledge → Ability → Reinforcement", "Individual-level change; identifying where someone is stuck"), listOf("Kotter's 8 Steps", "Urgency → Coalition → Vision → Communicate → Empower → Short-term wins → Consolidate → Anchor", "Organisational-level change"), listOf("Lewin's Model", "Unfreeze → Change → Refreeze", "Simple three-phase framework"), listOf("Bridges' Transition", "Ending → Neutral Zone → New Beginning", "Emotional/psychological side of change"))),
                s("Organisational Change Management Models", "ADKAR is the most tested change model. If a stakeholder knows about the change (Awareness) but does not want it (no Desire) — address the WHY, not the HOW. Do not jump to Knowledge/training when the barrier is Desire.", SectionKind.TIP),
                s("Knowledge Transfer and Organisational Learning", tableHeaders = listOf("Type", "Description", "How to Transfer"), tableRows = listOf(listOf("Explicit Knowledge", "Can be written down — procedures, data, manuals", "Documentation, databases, training materials"), listOf("Tacit Knowledge", "Experience-based; hard to articulate — intuition, judgment", "Mentoring, shadowing, communities of practice, storytelling"))),
                s("Knowledge Transfer and Organisational Learning", "• Lessons learned should be captured THROUGHOUT the project, not just at closure\n• Knowledge transfer to operations must happen BEFORE the team disbands\n• PMBOK 8: Manage Project Knowledge is a Governance process — it is a formal responsibility\n• Communities of practice, wikis, and post-implementation reviews support organisational learning"),
                s("Worked example — 📖 Worked Example: EEF vs OPA — Spotting the Difference", "Project: Launching a co-lending platform for a non-banking financial company (NBFC)\n\nENTERPRISE ENVIRONMENTAL FACTORS (things you CANNOT control):\n\n• RBI's new co-lending guidelines (Master Direction 2023) — you must comply, cannot change them\n\n• CIBIL and Experian credit bureau APIs — external systems you depend on\n\n• Interest rate environment — affects product viability but PM cannot control\n\n• Fintech startup culture — fast-moving, tolerates ambiguity\n\n• COVID-era WFH norms still affecting your team's in-person availability\n\n→ These CONSTRAIN and INFLUENCE your project. You ADAPT to them.\n\nORGANISATIONAL PROCESS ASSETS (things you CAN use and update):\n\n• Your company's project charter template (you fill it in; you can suggest updates to the template)\n\n• Lessons learned from the 2022 mobile lending app project\n\n• Standard risk register format from the PMO\n\n• Internal coding standards and security review checklist\n\n• Historical velocity data from previous agile projects\n\n→ These are TOOLS and KNOWLEDGE you leverage. You can also UPDATE them (lessons learned → future projects).\n\nExam tip — the quick test:\n\n\"Can the project team change this?\" → YES = OPA. NO = EEF.\n\n\"Is this internal to the organisation?\" → Usually YES = OPA. External market/legal/physical = EEF.", SectionKind.TIP),
                s("Worked example — 📖 Worked Example: ADKAR — Diagnosing the Barrier", "Project: Implementing a new digital underwriting system at an insurance company. 45 underwriters will move from email-based approvals to a workflow tool.\n\nThe problem: 3 months after go-live, only 30% of underwriters are using the new system. The rest still use email and spreadsheets.\n\nADKAR Diagnosis (interview 10 underwriters):\n\nAwareness — Do they know about the change?\n\n\"Yes, we heard about it.\" → A ✅\n\nDesire — Do they want to change?\n\n\"Honestly? No. Our spreadsheets work fine. The new system seems designed for IT people, not underwriters.\" → D ❌\n\nKnowledge — Do they know HOW to use it?\n\n(Irrelevant — they don't want to use it, so they haven't bothered learning)\n\nRoot cause identified: DESIRE barrier.\n\nThe training (Knowledge) and the mandate (Awareness) did nothing because nobody addressed WHY an underwriter would WANT to change.\n\nCorrect intervention:\n\n• Involve 3 senior underwriters in redesigning the workflow screens for their specific use case\n\n• Demonstrate \"what's in it for me\": the new system shows your SLA compliance score automatically — good for performance reviews\n\n• Give early adopters a \"Digital Underwriter\" recognition badge in internal comms\n\n• Walk the floor with the system for 2 weeks — hands-on support\n\nThree months later: 78% adoption. The remaining 22% are the near-retirement underwriters who have been given a 6-month transition period.\n\nLesson: Never jump to Knowledge/training when the barrier is Desire. They are two different problems requiring two different interventions.", SectionKind.TIP),
                s("Worked example — 📖 Worked Example: Portfolio → Program → Project Value Chain", "Organisation: A leading private sector bank — strategic goal: \"Double digital revenue by 2027\"\n\nPORTFOLIO level: \"Digital Transformation Portfolio\" — ₹500 crore approved for 2024–2027\n\nIncludes: Payments Program, Lending Program, Wealth Management Program, Core Infrastructure Upgrade\n\nPROGRAM level (Payments Program): Coordinate 6 related projects to create benefits beyond individual projects\n\n• Shared payment rails infrastructure (enables all payment projects)\n\n• Unified customer payment experience (cross-project consistency)\n\n• Regulatory compliance hub (built once, used by all payment projects)\n\nPROJECT level (UPI 2.0 Integration Project):\n\n• Scope: Integrate UPI Autopay, UPI Lite, and UPI One World for international users\n\n• Budget: ₹8 crore\n\n• Duration: 9 months\n\n• Benefits: 40% increase in recurring payment volume\n\nHOW each level adds value:\n\nPortfolio → ensures ₹500 crore goes to the RIGHT initiatives for the strategy\n\nProgram → ensures the 6 payment projects don't duplicate infrastructure or contradict each other\n\nProject → delivers the specific output (UPI integration) that enables the outcome (40% volume increase)\n\nWhy this matters for the exam:\n\n• Portfolio Manager asks: \"Is this the RIGHT project to fund?\" (Strategic alignment)\n\n• Program Manager asks: \"Are projects coordinated to maximise combined benefits?\"\n\n• Project Manager asks: \"Are we delivering on time, on budget, with the right quality?\"\n\nThese are three DIFFERENT success measures.", SectionKind.TIP),
                s("Organisational Change Management — Kotter's 8 Steps", tableHeaders = listOf("Step", "Name", "What It Means", "PM's Role"), tableRows = listOf(listOf("1", "Create urgency", "Make the status quo feel dangerous or unsustainable; why change NOW", "Share competitive data, performance gaps, regulatory threats that make the project critical"), listOf("2", "Form a guiding coalition", "Build a powerful group with authority, expertise, and credibility to lead the change", "Identify and engage champions at all levels — not just senior leaders"), listOf("3", "Form a strategic vision and initiatives", "Create a clear, compelling vision for the future state; define initiatives to achieve it", "Translate project objectives into a compelling \"what it will be like\" story"), listOf("4", "Enlist a volunteer army", "Build broad-based support across the organisation; engage the majority", "Change management plan; stakeholder engagement; address concerns proactively"), listOf("5", "Enable action by removing barriers", "Identify and remove structures, systems, or behaviours that block the change", "Resolve impediments; secure resources; resolve political obstacles"), listOf("6", "Generate short-term wins", "Plan and achieve visible, unambiguous early successes that build momentum", "Early delivery of high-value features; celebrate milestones; communicate wins widely"), listOf("7", "Sustain acceleration", "Use early wins to drive more change; do not declare victory too soon", "Keep the change program alive after initial enthusiasm fades; maintain leadership attention"), listOf("8", "Institute change", "Make the new behaviours permanent by connecting them to organisational culture and processes", "Training, updated SOPs, job descriptions, performance metrics aligned to new ways of working"))),
                s("Business Case — Contents and PM's Role", tableHeaders = listOf("Section", "Content", "PM's Involvement"), tableRows = listOf(listOf("Executive Summary", "One-page summary of the problem, proposed solution, benefits, cost, and recommendation", "PM may contribute; sponsor usually presents"), listOf("Problem/Opportunity Statement", "Clear articulation of the business problem or opportunity being addressed", "PM helps frame the problem in project terms"), listOf("Situation Analysis", "Current state analysis; root cause; gap analysis; stakeholder context", "PM contributes analysis; uses EEF and OPA data"), listOf("Option Analysis", "Alternatives considered (including \"do nothing\"); pros and cons of each", "PM evaluates delivery feasibility; feasibility of each option"), listOf("Recommended Solution", "The selected option with justification", "PM confirms deliverability of recommended option"), listOf("Financial Analysis", "NPV, IRR, Payback Period, ROI, BCR; cost-benefit analysis; assumptions", "PM provides project cost estimate; finance validates benefit projections"), listOf("Benefits and Success Criteria", "Specific, measurable benefits with realisation timeline; success metrics", "PM defines project success criteria; benefits owner defines business success metrics"), listOf("Risk Assessment", "High-level risks to delivery and benefits realisation", "PM provides delivery risk assessment"), listOf("Implementation Plan", "High-level approach, timeline, resource requirements", "PM provides the project delivery plan summary"), listOf("Approval and Authorisation", "Signatures from authorised decision-makers", "Sponsor signs; PM is named as the responsible PM"))),
                s("Business Case — Contents and PM's Role", "The business case is owned by the SPONSOR. The PM does NOT own the business case — the PM supports it, contributes to it, and is responsible for delivery against it. If the project's benefits case changes fundamentally mid-project, the SPONSOR decides whether to continue, modify, or terminate.", SectionKind.KEY),
                s("Programme vs Portfolio vs Project — Every Distinction", tableHeaders = listOf("Aspect", "Project", "Programme", "Portfolio"), tableRows = listOf(listOf("Definition", "Temporary unique endeavour delivering a specific output", "Group of related projects managed together to obtain benefits and control not available individually", "Collection of projects, programmes, and other work managed to achieve strategic objectives"), listOf("Duration", "Temporary — has a defined end", "Longer-term — ends when benefits are realised, not when last project closes", "Ongoing — continues as long as the organisation has strategic objectives"), listOf("Success measure", "On time, on budget, on scope (output delivered)", "Benefits realised collectively across projects; greater than the sum of parts", "Strategic value delivered; portfolio return on investment; strategic goal achievement"), listOf("Change approach", "Resist change — manage within the baseline", "Accept change — adapt programs and projects as the environment changes", "Expect change — portfolio is continuously reconfigured as strategy evolves"), listOf("Management focus", "Managing work: plans, resources, risks, quality", "Managing interdependencies: shared resources, integrated change, benefits flow", "Managing strategic investment: selecting, prioritising, balancing the portfolio"), listOf("Sponsor relationship", "Project sponsor is the key executive stakeholder", "Programme sponsor holds accountability across all component projects", "Portfolio governance board holds investment authority"), listOf("Risk management", "Manage individual project risks", "Manage risks across projects; protect the programme's combined benefits", "Manage strategic risk; balance risk across portfolio"), listOf("PMO role", "PM plans and executes", "Programme Manager coordinates and integrates", "Portfolio Manager selects and governs"))),
                s("PMO Types — Detailed", tableHeaders = listOf("PMO Type", "Authority Level", "What It Provides", "Examples of Services", "Exam Trigger"), tableRows = listOf(listOf("Supportive", "Low — advisory only", "Templates, training, lessons learned, best practices, tools, coaching on request", "PM asks for help → PMO provides. PMO has no oversight authority.", "Question says PMO \"provides templates\" or \"offers coaching\" → Supportive PMO"), listOf("Controlling", "Moderate — compliance required", "All Supportive services + requires adoption of specific frameworks, templates, and processes; monitors compliance", "PMO reviews project documents; requires use of standard risk register template; audits milestone reports.", "Question says PMO \"requires\" or \"ensures compliance\" → Controlling PMO"), listOf("Directive", "High — PMO manages projects", "All Controlling services + directly manages projects; PMs are PMO staff; PMO has full project authority", "PMO assigns PMs to projects; PMO controls resource pool; PMO makes project decisions; PMs report to PMO Head.", "Question says PMO \"assigns PM\" or \"directly manages\" → Directive PMO"))),
