                s("How to Use This Guide", tableHeaders = listOf("Week", "Focus", "Sections"), tableRows = listOf(listOf("Week 1", "Foundation & Mindset", "Exam Blueprint, PMBOK 8, PM Mindset"), listOf("Week 2", "Predictive Knowledge Areas", "Integration, Scope, Schedule, Cost & EVM"), listOf("Week 3", "Process & People Domains", "Quality, Risk, Stakeholders, Procurement, Leadership"), listOf("Week 4", "Business Environment & Agile", "Business Environment, Tailoring, Agile/Scrum/Hybrid"), listOf("Week 5", "Mock Exams & Review", "Full Cheat Sheet + external mock exams"))),
